  requires (len(xs) >= 0)
  ensures (result == (count x in xs: (x > t)))
  effects pure
  example (count_greater([1, 5, 3, 8], 3) == 2)
  example (count_greater([], 0) == 0)
  example (count_greater([4, 4], 3) == 2)
{
  match xs { [] => 0 [h, ..rest] => if (h > t) then (1 + count_greater(rest, t)) else count_greater(rest, t) }
}

