  ensures (result == len(xs))
  effects pure
  example (size([]) == 0)
  example (size([5, 6]) == 2)
{
  match xs { [] => 0 [_, ..t] => (1 + size(t)) }
}

fn occurrences(xs: List[Int], v: Int) -> Int
  requires (len(xs) >= 0)
  ensures (result == count(xs, v))
  effects pure
  example (occurrences([3, 1, 3], 3) == 2)
  example (occurrences([], 7) == 0)
{
  match xs { [] => 0 [h, ..t] => if (h == v) then (1 + occurrences(v, v)) else occurrences(t, v) }
}

fn pick(cands: List[Int], xs: List[Int]) -> Option[Int]
  requires (len(cands) >= 0)
  ensures match result { None => not (exists x in cands: ((2 * count(xs, x)) > len(xs))) Some(v) => (((2 * count(xs, v)) > len(xs)) and contains(cands, v)) }
  effects pure
  example (pick([3, 1, 3, 3], [3, 1, 3, 3]) == Some(3))
  example (pick([1, 2], [1, 2]) == None)
{
  match cands { [] => None [h, ..t] => if ((2 * occurrences(xs, h)) > size(xs)) then Some(h) else pick(t, xs) }
}

fn majority(xs: List[Int]) -> Option[Int]
  requires (len(xs) >= 0)
  ensures match result { None => not (exists x in xs: ((2 * count(xs, x)) > len(xs))) Some(v) => ((2 * count(xs, v)) > len(xs)) }
  effects pure
  example (majority([3, 1, 3, 3]) == Some(3))
  example (majority([1, 2]) == None)
  example (majority([]) == None)
  example (majority([5]) == Some(5))
{
  pick(xs, xs)
}

