  ensures ((result == Some(h)) or (result == o))
  effects pure
  example (better([1, 2, 2, 3], 2, None) == Some(2))
  example (better([1, 2, 2, 3], 1, Some(2)) == Some(2))
  example (better([1, 2, 2, 3], 3, Some(2)) == Some(2))
{
  match o { None => Some(h) Some(b) => if (occ(all, h) > occ(all, b)) then Some(h) else Some(b) }
}

fn pick(all: List[Int], rest: List[Int]) -> Option[Int]
  requires (len(rest) <= len(all))
  ensures match result { None => (len(rest) == 0) Some(v) => (contains(rest, v) and (forall x in rest: (count(all, x) <= count(all, v)))) }
  effects pure
  example (pick([1, 2, 2, 3], [1, 2, 2, 3]) == Some(2))
  example (pick([], []) == None)
  example (pick([5], [5]) == Some(5))
{
  match rest { [] => None [h, ..t] => better(all, h, pick(all, t)) }
}

